const mergeSchoolSettingsMessages = (language: AppLanguage) => {
  const base = schoolSettingsMessages.en;
  const full = schoolSettingsMessages[language as keyof typeof schoolSettingsMessages];
  const override = schoolSettingsOverrides[language as keyof typeof schoolSettingsOverrides];
  const source = full ?? override;

  if (!source) return base;

  return {
    ...base,
    ...source,
    actions: { ...base.actions, ...source.actions },
    badges: { ...base.badges, ...source.badges },
    labels: { ...base.labels, ...source.labels },
    messages: { ...base.messages, ...source.messages },
    categories: { ...base.categories, ...source.categories },
    settings: { ...base.settings, ...source.settings },
    options: { ...base.options, ...source.options },
  };
};

const mergeRoleDashboardMessages = (language: AppLanguage) => {
  const base = roleDashboardMessages.en;
  const source = roleDashboardMessages[language as keyof typeof roleDashboardMessages] || base;
  return {
    ...base,
    ...source,
    common: { ...base.common, ...source.common },
    teacher: { ...base.teacher, ...source.teacher },
    student: { ...base.student, ...source.student },
  };
};

const mergeAcademicYearsMessages = (language: AppLanguage) => {
  const base = academicYearsMessages.en;
  const source = academicYearsMessages[language as keyof typeof academicYearsMessages] || base;
  return {
    ...base,
    ...source,
    messages: { ...base.messages, ...source.messages },
  };
};

const mergeCalendarMessages = (language: AppLanguage) => {
  const base = calendarMessages.en;
  const source = calendarMessages[language as keyof typeof calendarMessages] || base;
  return {
    ...base,
    ...source,
    controls: { ...base.controls, ...source.controls },
    weekdays: { ...base.weekdays, ...source.weekdays },
    picker: { ...base.picker, ...source.picker },
    time: { ...base.time, ...source.time },
    form: { ...base.form, ...source.form },
    categories: { ...base.categories, ...source.categories },
  };
};

