const getLegacyModule = (language: AppLanguage, module: MessageModule) => {
  if (module === "communications") {
    return communicationsMessages[language as keyof typeof communicationsMessages] ?? communicationsMessages.en;
  }
  if (module === "navigation") return navigationMessages[language];
  if (module === "adminDashboard") return adminDashboardMessages[language];
  if (module === "schoolSettings") {
    return mergeSchoolSettingsMessages(language);
  }
  if (module === "peopleLists") {
    return peopleListMessages[language as keyof typeof peopleListMessages] ?? peopleListMessages.en;
  }
  if (module === "filters") {
    return filterMessages[language as keyof typeof filterMessages] ?? filterMessages.en;
  }
  if (module === "layout") {
    return layoutMessages[language as keyof typeof layoutMessages] ?? layoutMessages.en;
  }
  if (module === "breadcrumb") {
    return breadcrumbMessages[language as keyof typeof breadcrumbMessages] ?? breadcrumbMessages.en;
  }
  if (module === "announcements") {
    return announcementsPageMessages[language as keyof typeof announcementsPageMessages] ?? announcementsPageMessages.en;
  }
  if (module === "roleDashboard") {
    return mergeRoleDashboardMessages(language);
  }
  if (module === "academicYears") {
    return mergeAcademicYearsMessages(language);
  }
  if (module === "bulkUpload") {
    return bulkUploadMessages[language as keyof typeof bulkUploadMessages] ?? bulkUploadMessages.en;
  }
  if (module === "credentials") {
    return credentialsMessages[language as keyof typeof credentialsMessages] ?? credentialsMessages.en;
  }
  if (module === "calendar") {
    return mergeCalendarMessages(language);
  }
  if (module === "attendance") {
    return attendanceMessages[language as keyof typeof attendanceMessages] ?? attendanceMessages.en;
  }
  if (module === "timetable") {
    return timetableMessages[language as keyof typeof timetableMessages] ?? timetableMessages.en;
  }
  if (module === "assignments") {
    return assignmentsMessages[language as keyof typeof assignmentsMessages] ?? assignmentsMessages.en;
  }
  if (module === "parent") {
    return parentMessages[language as keyof typeof parentMessages] ?? parentMessages.en;
  }
  if (module === "students") {
    return studentDetailMessages[language as keyof typeof studentDetailMessages] ?? studentDetailMessages.en;
  }
  if (module === "login") {
    return loginMessages[language as keyof typeof loginMessages] ?? loginMessages.en;
  }
  if (module === "exams") {
    return examsMessages[language as keyof typeof examsMessages] ?? examsMessages.en;
  }

  const legacyKey = legacyModuleKeys[module];
  if (!legacyKey) return null;

  const messages = legacyMessagesByLanguage[language] as Record<string, unknown>;
  return messages[legacyKey] ?? null;
};

export function getDateLocale(language: AppLanguage) {
  return dateLocales[language] || dateLocales.en;
}

export function getModuleMessages<T = Record<string, unknown>>(
  language: AppLanguage,
  module: MessageModule,
): T {
  const moduleMessages =
    getLegacyModule(language, module) ??
    getLegacyModule("en", module) ??
    {};

  return moduleMessages as T;
}
